CREATE DATABASE IF NOT EXISTS bar_do_primo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bar_do_primo;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, email_verified_at TIMESTAMP NULL, password VARCHAR(255) NOT NULL, remember_token VARCHAR(100) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, contact_name VARCHAR(255) NULL, phone VARCHAR(30) NULL, email VARCHAR(255) NULL, city VARCHAR(255) NULL, notes TEXT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, name VARCHAR(255) NOT NULL, sku VARCHAR(50) NOT NULL UNIQUE, unit VARCHAR(12) NOT NULL DEFAULT 'un', current_stock DECIMAL(12,3) NOT NULL DEFAULT 0, minimum_stock DECIMAL(12,3) NOT NULL DEFAULT 0, purchase_price DECIMAL(12,2) NULL, sale_price DECIMAL(12,2) NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX products_stock_idx(active,current_stock), CONSTRAINT products_category_fk FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE inventory_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, supplier_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, type ENUM('entrada','saida','ajuste') NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_cost DECIMAL(12,2) NULL, reference VARCHAR(100) NULL, notes TEXT NULL, moved_at TIMESTAMP NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX movements_product_date_idx(product_id,moved_at), CONSTRAINT movements_product_fk FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT, CONSTRAINT movements_supplier_fk FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL, CONSTRAINT movements_user_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
